package ai.moying.iview.plan
import ai.moying.iview.common.ApiResponse
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.*
import java.time.*
class ShiftRequest{var name:String="";var startMinute:Int?=null;var endMinute:Int?=null;var weekdays:Set<DayOfWeek>?=null;var zoneId:String?=null;var enabled:Int?=null};class DowntimeRequest{var deviceId:Long?=null;var start:Instant?=null;var end:Instant?=null;var reason:String=""}
@RestController @RequestMapping("/api/v1/shifts") class ShiftController(private val s:ProductionPlanService){@GetMapping fun list()=ApiResponse.success(s.shifts());@PostMapping @ResponseStatus(HttpStatus.CREATED)fun create(@RequestBody b:ShiftRequest)=ApiResponse.success(s.createShift(b.c()));@PutMapping("/{id}")fun update(@PathVariable id:Long,@RequestBody b:ShiftRequest):ApiResponse<Shift>{val o=s.shifts().find{it.id==id}?:throw ProductionPlanNotFoundException("班次不存在: $id");return ApiResponse.success(s.updateShift(id,b.c(o)))};@DeleteMapping("/{id}")fun delete(@PathVariable id:Long):ApiResponse<Nothing>{s.deleteShift(id);return ApiResponse.success()};private fun ShiftRequest.c(o:Shift?=null)=ShiftCommand(name.ifBlank{o?.name?:""},startMinute?:o?.startMinute?:-1,endMinute?:o?.endMinute?:-1,weekdays?:o?.weekdays?:emptySet(),zoneId?:o?.zoneId?:"Asia/Shanghai",enabled?.let{it==1}?:o?.enabled?:true)}
@RestController @RequestMapping("/api/v1/planned-downtimes") class DowntimeController(private val s:ProductionPlanService){@GetMapping fun list(@RequestParam deviceId:Long,@RequestParam start:Instant,@RequestParam end:Instant)=ApiResponse.success(s.downtime(deviceId,start,end));@PostMapping @ResponseStatus(HttpStatus.CREATED)fun create(@RequestBody b:DowntimeRequest)=ApiResponse.success(s.createDowntime(PlannedDowntimeCommand(b.deviceId,b.start?:Instant.MIN,b.end?:Instant.MIN,b.reason)));@DeleteMapping("/{id}")fun delete(@PathVariable id:Long):ApiResponse<Nothing>{s.deleteDowntime(id);return ApiResponse.success()}}
